import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"CoreLib Actions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/item/corelib-actions.md","filePath":"en/modules/item/corelib-actions.md","lastUpdated":0}`),a={name:`en/modules/item/corelib-actions.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="corelib-actions" tabindex="-1">CoreLib Actions <a class="header-anchor" href="#corelib-actions" aria-label="Permalink to “CoreLib Actions”">​</a></h1><p>When EmakiItem is enabled, it adds main-hand update, rerender, repair, and durability stages to the CoreLib action registry, along with vanilla Data Component add, modify, and remove stages.</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>This page documents only the stages registered by EmakiItem. CoreLib built-in stages are documented in <a href="./../corelib/actions.html">CoreLib Actions</a>. Current stage IDs use only the canonical names below; historical aliases are no longer registered. The old <code>emakiitem_update</code> is now written <code>item_update</code>, the others follow the same rule, and the old colon form <code>emakiitem:component_add</code> is now <code>item_component_add</code>.</p></div><h2 id="stage-ids" tabindex="-1">Stage IDs <a class="header-anchor" href="#stage-ids" aria-label="Permalink to “Stage IDs”">​</a></h2><table tabindex="0"><thead><tr><th>Stage ID</th><th>Purpose</th><th>Target requirement</th><th>Parameters</th></tr></thead><tbody><tr><td><code>item_update</code></td><td>Forces the main-hand item through EmakiItem&#39;s update service.</td><td><code>REQUIRED_ENTITY</code></td><td>none</td></tr><tr><td><code>item_rerender</code></td><td>Rebuilds the main-hand item presentation through CoreLib item assembly.</td><td><code>REQUIRED_ENTITY</code></td><td>none</td></tr><tr><td><code>item_repair_amount</code></td><td>Repairs the main-hand item by a damage amount.</td><td><code>REQUIRED_ENTITY</code></td><td><code>amount</code></td></tr><tr><td><code>item_damage</code></td><td>Adds damage to the main-hand item.</td><td><code>REQUIRED_ENTITY</code></td><td><code>amount</code></td></tr><tr><td><code>item_set_damage</code></td><td>Sets the main-hand item&#39;s current damage value.</td><td><code>REQUIRED_ENTITY</code></td><td><code>value</code></td></tr><tr><td><code>item_set_durability</code></td><td>Sets the main-hand item&#39;s remaining durability value.</td><td><code>REQUIRED_ENTITY</code></td><td><code>value</code></td></tr><tr><td><code>item_component_add</code></td><td>Adds one Data Component and fails if it is already present.</td><td><code>OPTIONAL</code></td><td><code>component</code>, <code>value</code>, optional <code>slot</code></td></tr><tr><td><code>item_component_modify</code></td><td>Modifies an existing Data Component and fails if it is absent.</td><td><code>OPTIONAL</code></td><td><code>component</code>, <code>value</code>, optional <code>slot</code></td></tr><tr><td><code>item_component_remove</code></td><td>Removes one Data Component and idempotently skips if it is absent.</td><td><code>OPTIONAL</code></td><td><code>component</code>, optional <code>slot</code></td></tr><tr><td><code>item_state_set</code></td><td>Sets a typed persistent item state.</td><td><code>OPTIONAL</code></td><td><code>key</code>, <code>type</code>, <code>value</code>, optional <code>slot</code></td></tr><tr><td><code>item_state_add</code></td><td>Adds to a numeric persistent item state.</td><td><code>OPTIONAL</code></td><td><code>key</code>, <code>type</code>, <code>amount</code>, optional <code>slot</code></td></tr><tr><td><code>item_state_remove</code></td><td>Removes a persistent item state.</td><td><code>OPTIONAL</code></td><td><code>key</code>, <code>type</code>, optional <code>slot</code></td></tr><tr><td><code>item_state_refresh</code></td><td>Refreshes the target item while preserving its persistent state.</td><td><code>OPTIONAL</code></td><td>optional <code>slot</code></td></tr></tbody></table><h2 id="gate-ids" tabindex="-1">Gate IDs <a class="header-anchor" href="#gate-ids" aria-label="Permalink to “Gate IDs”">​</a></h2><table tabindex="0"><thead><tr><th>Gate ID</th><th>Purpose</th><th>Parameters</th><th>Provided variables</th></tr></thead><tbody><tr><td><code>item_state_read</code></td><td>Reads one persistent item state into pipeline variables.</td><td><code>key</code>, <code>type</code>, optional <code>slot</code></td><td><code>item_state.value</code>, <code>item_state.exists</code>, <code>item_state.key</code>, <code>item_state.type</code></td></tr></tbody></table><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h2><h3 id="update-and-durability-stages" tabindex="-1">Update and durability stages <a class="header-anchor" href="#update-and-durability-stages" aria-label="Permalink to “Update and durability stages”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>amount</code></td><td>INTEGER</td><td>Yes (<code>item_repair_amount</code>, <code>item_damage</code>)</td><td>—</td><td>Repair or damage amount. Negative values are treated as 0.</td></tr><tr><td><code>value</code></td><td>INTEGER</td><td>Yes (<code>item_set_damage</code>, <code>item_set_durability</code>)</td><td>—</td><td>Target damage value or target remaining durability value.</td></tr></tbody></table><p><code>item_update</code> and <code>item_rerender</code> read no parameters.</p><h3 id="component-stages" tabindex="-1">Component stages <a class="header-anchor" href="#component-stages" aria-label="Permalink to “Component stages”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>component</code></td><td>STRING</td><td>Yes</td><td>—</td><td>Data Component ID. IDs without a namespace resolve as <code>minecraft:</code>.</td></tr><tr><td><code>value</code></td><td>STRING</td><td>Yes (<code>add</code> / <code>modify</code>)</td><td>—</td><td>JSON-ish component value: JSON objects and arrays, quoted strings, booleans, numbers, <code>null</code>, and plain strings are supported. A malformed structured value fails the stage.</td></tr><tr><td><code>slot</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Explicit player inventory slot. When blank, the target is resolved in the order below.</td></tr></tbody></table><p><code>item_component_remove</code> has only <code>component</code> and <code>slot</code>; it has no <code>value</code>.</p><h3 id="item-state-stages-and-gate" tabindex="-1">Item state stages and gate <a class="header-anchor" href="#item-state-stages-and-gate" aria-label="Permalink to “Item state stages and gate”">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>key</code></td><td>STRING</td><td>Yes (except <code>item_state_refresh</code>)</td><td>—</td><td>Item-state field name.</td></tr><tr><td><code>type</code></td><td>STRING</td><td>Yes (except <code>item_state_refresh</code>)</td><td>—</td><td>Item-state type.</td></tr><tr><td><code>value</code></td><td>STRING</td><td>Yes (<code>item_state_set</code>)</td><td>—</td><td>Field value to write.</td></tr><tr><td><code>amount</code></td><td>DOUBLE</td><td>Yes (<code>item_state_add</code>)</td><td>—</td><td>Numeric delta.</td></tr><tr><td><code>slot</code></td><td>STRING</td><td>No</td><td><code>&quot;&quot;</code></td><td>Explicit player inventory slot; slot names match the Component stages.</td></tr></tbody></table><p><code>item_state_refresh</code> takes only the optional <code>slot</code>. <code>item_state_read</code> is a gate rather than a stage and takes <code>key</code>, <code>type</code>, and an optional <code>slot</code>.</p><h2 id="component-target-resolution" tabindex="-1">Component target resolution <a class="header-anchor" href="#component-target-resolution" aria-label="Permalink to “Component target resolution”">​</a></h2><p>Component stages resolve the item to patch in this order:</p><ol><li>An explicit <code>slot</code> argument.</li><li>The pipeline item (<code>CoreActionKeys.ITEM</code>, published by stages such as <code>create_item</code>).</li><li>The target player&#39;s main hand.</li></ol><p>An explicit <code>slot</code> wins over the pipeline item because naming a slot is a deliberate instruction, not a fallback. The pipeline item is patched in place: later stages read the same reference, so replacing it would leave them looking at the unpatched copy.</p><p>The three component stages declare <code>OPTIONAL</code> rather than <code>REQUIRED_ENTITY</code>: as long as the pipeline carries an item, they can run without a player target.</p><h3 id="supported-slots" tabindex="-1">Supported slots <a class="header-anchor" href="#supported-slots" aria-label="Permalink to “Supported slots”">​</a></h3><p>Slot names follow CoreLib&#39;s shared slot table:</p><ul><li>Main hand: <code>mainhand</code>, <code>main_hand</code>, <code>hand</code></li><li>Off hand: <code>offhand</code>, <code>off_hand</code></li><li>Armor: <code>helmet</code>, <code>chestplate</code> / <code>chest</code>, <code>leggings</code> / <code>legs</code>, <code>boots</code></li><li>Inventory indices: <code>0</code> through <code>35</code>, also written <code>slot_12</code> or <code>hotbar_0</code></li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_update&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_repair_amount amount=25&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_damage amount=10&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_set_durability value=100&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_component_add component=max_stack_size value=16&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_component_modify component=enchantment_glint_override value=true slot=mainhand&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_component_remove component=custom_name slot=offhand&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Patch the pipeline item instead of something in the inventory</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | create_item item_source=minecraft-diamond_sword | item_component_add component=max_stack_size value=1 | send_item&#39;</span></span></code></pre></div><p>Quote values that contain spaces or structured content:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>self | item_component_modify component=custom_name value=&#39;&lt;gold&gt;Forged Blade&lt;/gold&gt;&#39;</span></span>
<span class="line"><span>self | item_component_add component=custom_data value=&#39;{&quot;emaki&quot;:{&quot;source&quot;:&quot;forge&quot;}}&#39;</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to “Notes”">​</a></h2><ul><li>Update and durability stages operate on the target player&#39;s main-hand item and are skipped when the main hand is empty. On success they report <code>changed</code>, <code>damage</code>, and <code>max_damage</code>.</li><li><code>item_set_durability</code> makes no change when the item has no maximum durability. Damage values are clamped to <code>[0, max_damage]</code>, and dropping below the maximum clears the repair disabled flag.</li><li><code>item_component_add</code> on an existing component and <code>item_component_modify</code> on a missing one both fail with <code>REJECTED</code> instead of silently correcting themselves, because either case means the configuration is wrong. <code>item_component_remove</code> treats a missing component as skipped.</li><li>Component patches are applied through CoreLib <code>ConfiguredItemDefinition</code>, preserving third-party source identity, PDC, and unrelated components.</li><li>On success, component stages report <code>component</code>, <code>target</code>, <code>changed</code>, and <code>existed_before</code>. <code>target</code> is either the slot name or <code>pipeline:item</code>.</li><li>An empty (air) target item is skipped. If none of the three resolution paths finds an item, the stage fails.</li></ul>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};